// Un rând = succes (token + profil); zero rânduri = credențiale greșite
const row = $input.all().map(i => i.json).find(r => r && r.id && r.token);
if (row) {
  return [{ json: { statusCode: 200, body: {
    token: row.token,
    expires_at: row.expires_at,
    user: { id: row.id, email: row.email, name: row.name, auth_provider: row.auth_provider }
  } } }];
}
return [{ json: { statusCode: 401, body: { status: 'error', message: 'Email sau parolă incorectă' } } }];

// Validare pe server (aplicația validează și ea, dar serverul nu are încredere în client)
const b = $json.body || {};
const email = String(b.email || '').trim().toLowerCase();
const name = String(b.name || '').trim();
const password = String(b.password || '');
const errors = [];
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('Email invalid');
if (password.length < 6) errors.push('Parola trebuie să aibă cel puțin 6 caractere');
if (!name || name.length > 120) errors.push('Numele este obligatoriu (max. 120 caractere)');
if (errors.length) {
  return [{ json: { valid: false, statusCode: 400, body: { status: 'error', message: errors.join('. ') } } }];
}
return [{ json: { valid: true, email, name, password } }];

// Un rând = succes (token + profil); zero rânduri = email deja folosit
const row = $input.all().map(i => i.json).find(r => r && r.id && r.token);
if (row) {
  return [{ json: { statusCode: 200, body: {
    token: row.token,
    expires_at: row.expires_at,
    user: { id: row.id, email: row.email, name: row.name, auth_provider: row.auth_provider }
  } } }];
}
return [{ json: { statusCode: 409, body: { status: 'error', message: 'Există deja un cont cu acest email' } } }];

// Serverul NU are încredere în email-ul trimis de aplicație: întreabă direct Clerk
// cui aparține access token-ul (endpoint-ul OIDC /oauth/userinfo).
const body = $json.body || {};
const token = String(body.access_token || '');
const domain = String($env.CLERK_DOMAIN || '').replace(/^https?:\/\//, '').replace(/\/+$/, '');
const fail = (statusCode, message) => [{ json: { ok: false, statusCode, body: { status: 'error', message } } }];

if (!domain) return fail(500, 'CLERK_DOMAIN nu este configurat pe serverul n8n.');
if (!token) return fail(400, 'Token Google lipsă.');

// returnFullResponse + ignoreHttpStatusErrors: statusul vine în răspuns (în task runner-ul
// n8n 2.x, eroarea aruncată nu conține codul HTTP).
let res;
try {
  res = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://${domain}/oauth/userinfo`,
    headers: { Authorization: `Bearer ${token}` },
    json: true,
    timeout: 10000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
} catch (e) {
  return fail(502, 'Nu s-a putut contacta Clerk pentru verificarea autentificării.');
}
const status = Number(res.statusCode || 0);
if (status === 401 || status === 403) return fail(401, 'Token Google invalid sau expirat.');
if (status < 200 || status >= 300) return fail(502, `Clerk a răspuns cu HTTP ${status}.`);
let info = res.body;
if (typeof info === 'string') { try { info = JSON.parse(info); } catch (_) { info = {}; } }

const email = String(info.email || '').trim().toLowerCase();
if (!email) return fail(401, 'Contul Google nu are o adresă de email.');
if (info.email_verified === false) return fail(401, 'Adresa de email Google nu este verificată.');
const name = String(info.name || [info.given_name, info.family_name].filter(Boolean).join(' ') || email.split('@')[0])
  .trim().slice(0, 120);
return [{ json: { ok: true, email, name } }];

// Un rând = succes (token + profil); zero rânduri = email folosit de un cont cu parolă
const row = $input.all().map(i => i.json).find(r => r && r.id && r.token);
if (row) {
  return [{ json: { statusCode: 200, body: {
    token: row.token,
    expires_at: row.expires_at,
    user: { id: row.id, email: row.email, name: row.name, auth_provider: row.auth_provider }
  } } }];
}
return [{ json: { statusCode: 409, body: { status: 'error', message: 'Acest email are deja un cont cu parolă. Autentifică-te cu email și parolă.' } } }];

