const query = $('Webhook GET /news').first().json.query || {};
const allowed = String(query.categories || '').split(',').map(c => c.trim().toLowerCase()).filter(Boolean);
const exclude = new Set(String(query.exclude || '').split(',').map(id => id.trim()).filter(Boolean));

const list = $input.all()
  .map(item => item.json)
  .filter(a => a && a.id)                       // alwaysOutputData produce {} când tabela e goală
  .filter(a => !exclude.has(a.id))
  .filter(a => allowed.length === 0 || allowed.includes(String(a.category || '').toLowerCase()))
  .slice(0, 50);

// Un singur item cu lista: răspunsul este mereu un array JSON valid (și [] când nu sunt știri).
return [{ json: { list } }];

