// „Aprofundează subiectul”: analiză generată o singură dată per articol, apoi servită din cache.
const row = $input.first().json || {};
if (!row.id) return [{ json: { statusCode: 404, save: false, body: { status: 'error', message: 'Articolul nu există.' } } }];
if (row.deep_dive) return [{ json: { statusCode: 200, save: false, body: { article_id: row.id, deep_dive: row.deep_dive } } }];

const key = $env.GEMINI_API_KEY || '';
if (!key) return [{ json: { statusCode: 503, save: false, body: { status: 'error', message: 'Analiza AI nu este configurată pe server.' } } }];

const content = String(row.full_content || row.ai_summary || row.summary || '').slice(0, 10000);
const prompt = `Ești un jurnalist analist. Pentru articolul de mai jos scrie în limba ROMÂNĂ o aprofundare de 150-220 de cuvinte, cu exact aceste trei secțiuni, fiecare începând pe un rând nou cu titlul urmat de două puncte:
Context:
De ce contează:
Ce urmează:
Folosește doar informații din articol și cunoștințe generale sigure. Nu inventa cifre, nume sau citate. Răspunde doar cu textul, fără markdown.

Titlu: ${row.title}

Articol:
${content}`;

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-lite-latest:generateContent?key=${key}`,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.4, maxOutputTokens: 700 }
    }),
    json: false,
    timeout: 25000
  });
  const data = typeof response === 'string' ? JSON.parse(response) : response;
  const text = data?.candidates?.[0]?.content?.parts?.[0]?.text?.replace(/\*\*/g, '').trim();
  if (!text) throw new Error('Răspuns AI gol');
  return [{ json: { statusCode: 200, save: true, body: { article_id: row.id, deep_dive: text } } }];
} catch (e) {
  return [{ json: { statusCode: 502, save: false, body: { status: 'error', message: 'Serviciul AI nu a răspuns. Încearcă din nou.' } } }];
}
